/** Raças dos livros importados (chave da entrada, em português) → ícone da espécie parecida. */
const SPECIES_ALIASES: Record<string, string> = {
  anao: 'dwarf', duergar: 'dwarf', elfo: 'elf', 'meio-elfo': 'elf', eladrin: 'elf', 'elfo-do-mar': 'elf', 'shadar-kai': 'elf',
  halfling: 'halfling', pequenino: 'halfling', humano: 'human', draconato: 'dragonborn', gnomo: 'gnome', 'gnomo-das-profundezas': 'gnome',
  'meio-orc': 'orc', orc: 'orc', bugurso: 'orc', goblin: 'orc', hobgoblin: 'orc', tiefling: 'tiefling', tiferino: 'tiefling',
  golias: 'goliath', goliath: 'goliath', firbolg: 'goliath',
};
/** Classes dos livros importados → ícone de uma classe parecida (o Artífice usa o do Mago). */
const CLASS_ALIASES: Record<string, string> = { artificer: 'wizard', artifice: 'wizard' };

/**
 * Ícone de uma classe ou espécie do SRD (`dwarf`) ou de livro importado (`phb-2014:anao`): o do
 * SRD de mesmo nome, ou um genérico (humano / guerreiro) para que nenhuma opção fique sem ícone.
 */
export function findCharacterIcon(kind: 'class' | 'species', id: string): GameIcon | undefined {
  const direct = characterIcons[kind][id];
  if (direct) return direct;
  const key = id.includes(':') ? id.slice(id.indexOf(':') + 1) : id;
  const aliases = kind === 'species' ? SPECIES_ALIASES : CLASS_ALIASES;
  const alias = aliases[key] ?? Object.entries(aliases).find(([name]) => key.startsWith(`${name}-`))?.[1];
  return characterIcons[kind][alias ?? key] ?? (id.includes(':') ? characterIcons[kind][kind === 'species' ? 'human' : 'fighter'] : undefined);
}

