/** Ícone do antecedente pelo nome ("Acólito", "Herói do Povo"…), ou o genérico. */
export function findBackgroundIcon(name: string): GameIcon {
  const key = name
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/\(.*?\)/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
  return backgroundIcons[key] ?? backgroundIcons._padrao!;
}
